+++ b/src/geo.ts
@@ -1,11 +1,30 @@
 export type LatLng = { lat: number; lng: number };
+
+const EARTH_RADIUS_KM = 6371.0088;
+
+export function isLatLng(p: unknown): p is LatLng {
+  if (typeof p !== "object" || p === null) return false;
+  const { lat, lng } = p as { lat: unknown; lng: unknown };
+  return typeof lat === "number" && typeof lng === "number" && lat >= -90 && lat <= 90 && lng >= -180 && lng <= 180;
+}

 /** Great-circle distance in kilometres. */
 export function haversineKm(a: LatLng, b: LatLng): number {
-  throw new Error("not implemented");
+  if (!isLatLng(a) || !isLatLng(b)) throw new RangeError("coordinates must be finite, lat -90..90, lng -180..180");
+  const toRad = Math.PI / 180;
+  const dLat = (b.lat - a.lat) * toRad;
+  const dLng = (b.lng - a.lng) * toRad;
+  const h =
+    Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * toRad) * Math.cos(b.lat * toRad) * Math.sin(dLng / 2) ** 2;
+  return 2 * EARTH_RADIUS_KM * Math.asin(Math.min(1, Math.sqrt(h)));
 }

 /** Delivery zone "A" to "E" for a distance in kilometres. */
 export function zoneFor(distanceKm: number): "A" | "B" | "C" | "D" | "E" {
-  throw new Error("not implemented");
+  if (!Number.isFinite(distanceKm) || distanceKm < 0) throw new RangeError("distance must be a non-negative number");
+  if (distanceKm <= 25) return "A";
+  if (distanceKm <= 100) return "B";
+  if (distanceKm <= 400) return "C";
+  if (distanceKm <= 1000) return "D";
+  return "E";
 }
